const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const COPY={es:{title:'Seguridad de tu operación',overview:'Resumen',assets:'Activos',staff:'Personal',orders:'Órdenes',history:'Historial',build:'Construir',manage:'Gestionar oficina',close:'Cerrar',score:'Índice HSEC',critical:'Riesgos críticos',safe:'Sin riesgos críticos detectados',mission:'MISIÓN 2 · PREPARA TU OPERACIÓN',inspection:'Iniciar inspección',hire:'Contratar',equal:'Mismas competencias, costo y progresión para ambos candidatos.',parity:'Paridad informativa',small:'Dotación pequeña: no representa una tendencia de paridad. No modifica el puntaje.',pending:'Pendiente',preview:'Vista previa editable',place:'Ubicar elemento',confirm:'Confirmar construcción',cancel:'Cancelar',rotate:'Girar',undo:'Deshacer punto',reset:'Ruta sugerida',route:'Toca el terreno para añadir puntos. Se ajustan a los accesos y a una cuadrícula de 0,5 m.',prop:'Toca el terreno o usa los controles para ubicarlo. Mantén libres los accesos.',cost:'Costo',duration:'Montaje',life:'Vida útil de referencia',days:'días de juego',benefit:'Función',empty:'Todavía no hay elementos en esta sección.',boost:'Completar con acelerador',inspect:'Inspeccionar cerca del activo',repair:'Reparar aquí',assign:'Asignar al prevencionista',remove:'Retirar activo',upgrade:'Mejorar superficie',future:'Etapa posterior',return:'Volver al catálogo',detected:'Detectada',physical:'Estructura',visual:'Apariencia',functional:'Operación',complete:'Operación preparada',reward:'Inspección aprobada · recompensa entregada una sola vez.',coverage:'Cobertura de iluminación',routes:'Redes conectadas',npc:'Prevencionista',idle:'Disponible',walking:'En recorrido',resting:'Fuera de turno',blocked:'Ruta bloqueada',inspecting:'Inspeccionando',maintaining:'Mantenimiento ligero',routing:'Preparando recorrido',building:'En montaje',built:'Instalado',verification:'Verificando',executing:'En ejecución',assigned:'Asignada',completed:'Completada',running:'En curso',inspected:'Inspección registrada',construction:'Montaje iniciado',staffReady:'Prevencionista contratado',kit:'Conos del kit disponibles',noCash:'Créditos insuficientes',grant:'Capital inicial HSEC',access:'Accesos y conexiones',noOffline:'El desgaste avanza con el tiempo de juego. No hay deterioro mientras la partida está cerrada.'},en:{title:'Operational safety',overview:'Overview',assets:'Assets',staff:'Staff',orders:'Work orders',history:'History',build:'Build',manage:'Manage office',close:'Close',score:'HSEC score',critical:'Critical risks',safe:'No critical risks detected',inspection:'Start inspection',hire:'Hire',preview:'Editable preview',confirm:'Confirm construction',cancel:'Cancel',rotate:'Rotate',undo:'Undo point',reset:'Suggested route',cost:'Cost',duration:'Assembly',benefit:'Function',return:'Back to catalog',empty:'No items in this section yet.',mission:'MISSION 2 · PREPARE YOUR OPERATION'}};
export class HsecUI{
 constructor(options){Object.assign(this,options);this.tab='overview';this.category='infrastructure';this.selected='shed';this.mode=false;this.panelOpen=false;this.drawing=null;this.coneZone=null;this.cachedEval=null;this.button=document.createElement('button');this.button.id='hsecButton';this.button.className='hsecHud hidden';this.button.onclick=()=>this.open();(document.querySelector('.topActions')||document.querySelector('#hud')).prepend(this.button);}
 L(k){const lang=this.state()?.lang||'es';return COPY[lang]?.[k]||COPY.es[k]||k;}
 run(fn,feedback){try{fn();this.onSave();this.cachedEval=null;if(feedback)this.notify(feedback);this.refresh();return true;}catch(e){this.notify(e.message||'No fue posible completar la acción');return false;}}
 update(){const s=this.state(),on=!!s&&active(s);const m2Done=!!s?.hsec?.completedAt;this.button.classList.toggle('hidden',!on||m2Done);if(!on)return;const h=ensureHsec(s),e=this.cachedEval||evaluation(s);const hudKey=e.total+':'+e.critical.length;if(hudKey!==this.lastHudKey){this.lastHudKey=hudKey;if(!m2Done){this.button.innerHTML=hsecIcon('management',true)+`<b>${e.total}</b><span>HSEC</span>`;this.button.classList.toggle('warning',!!e.critical.length);}this.button.setAttribute('aria-label',this.L('score')+' '+e.total+' / 100');}/* Update inline HSEC indicator in objective panel */const hsecInline=document.querySelector('#hsecInline');if(hsecInline&&m2Done){hsecInline.classList.toggle('hidden',false);hsecInline.innerHTML=`${hsecIcon('management',true)}<span>HSEC <b>${e.total}</b>/100</span>`;hsecInline.classList.toggle('hsecWarning',e.total<80||!!e.critical.length);}if(this.panelOpen){
   const n=document.querySelector('#hsecNpcState');if(n)n.textContent=this.L(h.employee?.state||'idle');
   updateShedProgressNodes(document.querySelector('#modalCard'),h);
  }}
 refresh(){this.cachedEval=evaluation(this.state());this.update();if(this.panelOpen)this.open(this.tab);if(this.builder&&this.mode&&!this.panelOpen)this.builder.render();}
 open(tab='overview'){if(!active(this.state()))return;this.tab=tab;this.panelOpen=true;this.onStop?.();this.closeBuilder?.();const s=this.state(),h=ensureHsec(s),e=evaluation(s);this.cachedEval=e;const heading=`<span class="eyebrow">${this.L('mission')}</span><div class="hsecHeading"><h2>${this.L('title')}</h2><strong class="hsecScore">${e.total}<small>/100</small></strong></div><nav class="hsecTabs">${['overview','assets','staff','orders','history'].map(k=>`<button data-hsec-tab="${k}" class="${k===tab?'selected':''}">${this.L(k)}</button>`).join('')}</nav>`;
 let body='';if(tab==='overview'){
 const step=missionStep(s),checks=mission2Readout(s),activeShed=h.assets.find(a=>a.type==='shed'&&a.status==='building');
 const liveChecklist=`<section class="hsecLiveChecklist" aria-label="Checklist misión 2">
  <div class="hsecChecklistHeading"><b>REQUISITOS REALES · ${checks.done}/${checks.total}</b><small>${checks.confirmed?'Misión completada':'Siguiente: '+esc(checks.pending?.name||'Confirmar misión')}</small></div>
  ${checks.items.map(item=>`<div class="hsecRequirement ${item.done?'done':'pending'}"><span class="hsecRequirementIcon">${item.done?'✓':'○'}</span>
   <span class="hsecRequirementCopy"><strong>${esc(item.name)}</strong><small>${esc(item.value)}</small>
   ${item.progress?`<progress class="hsecRoadMeters" max="${item.progress.max}" value="${Math.min(item.progress.max,item.progress.value)}" aria-label="Metros de camino vehicular construidos"></progress>`:''}
   ${item.id==='shed'&&activeShed?renderShedProgress(activeShed,h):''}
   ${item.done?'':`<em>${esc(item.hint)}</em>`}</span>
   <b>${item.done?'Cumplido':'Pendiente'}</b>
  </div>`).join('')}</section>`;
 body=`${liveChecklist}<div class="hsecNext"><b>${h.completedAt?this.L('complete'):esc(HSEC_STEPS[step]||HSEC_STEPS[4])}</b><small>${h.completedAt?this.L('reward'):`Objetivo ${Math.min(step+1,5)} de 5 · ${this.L('coverage')} ${Math.round(e.light*100)} % · Kit: ${h.kitCones} conos`}</small></div>${e.critical.length?`<h3>${this.L('critical')}</h3><div class="hsecRisks">${e.critical.map(c=>`<div>${hsecIcon(c.category,true)}<span>${esc(c.text)}</span><button data-goto="${c.point?.x??0},${c.point?.z??0}" title="Ver ubicación">${icon('location')}</button></div>`).join('')}</div>`:`<p>${this.L('safe')}</p>`}<div class="hsecActions"><button data-action="build" class="primary">${icon('build')}${this.L('build')}</button><button data-action="office">${this.L('manage')}</button><button data-action="inspection" ${h.employee?'':'disabled'}>${this.L('inspection')}</button></div><div class="hsecCategories">${SC.map((c,i)=>`<div style="--accent:${c.color}">${hsecIcon(c.id)}<span>${esc(c.name)}<progress max="${c.max}" value="${e.scores[i]}"></progress></span><b>${e.scores[i]}<small>/${c.max}</small></b></div>`).join('')}</div><small>Inventario: ${s.inventory.length} / ${inventoryCapacity(s)}</small><details class="hsecStages"><summary>Etapas orientativas</summary><ol>${HSEC_STEPS.map((text,i)=>`<li class="${i<step?'done':''}">${esc(text)}</li>`).join('')}</ol></details>`;}
 if(tab==='assets')body=h.assets.length?h.assets.map(a=>{const d=assetDefinition(a.type);return `<article class="hsecAsset">${hsecIcon(d.category)}<div><b>${esc(d.name)} · N${a.level}</b><small>${a.id} · ${this.L(a.status)}${a.status==='building'?' · '+Math.max(0,Math.ceil(a.ends-h.time))+' s':''}</small>${a.type==='shed'&&a.status==='building'?renderShedProgress(a,h):''}<div class="conditionBars">${Object.entries(a.condition).map(([k,v])=>`<span>${this.L(k)} <b>${Math.round(v)}%</b><progress max="100" value="${v}"></progress></span>`).join('')}</div><small>${this.L('life')}: ${a.lifeDays} ${this.L('days')} · ${esc(d.maintenance)}</small><div class="hsecActions">${a.status==='building'?`<button data-boost="${a.id}" ${s.boosters>0?'':'disabled'}>${this.L('boost')} (${s.boosters})</button>`:`<button data-inspect="${a.id}">${this.L('inspect')}</button>${d.route&&a.level<3?`<button data-upgrade="${a.id}">${this.L('upgrade')} · N${a.level+1}</button>`:''}<button data-remove="${a.id}">${this.L('remove')}</button>`}</div></div></article>`;}).join(''):`<p>${this.L('empty')}</p><button data-action="build" class="primary">${this.L('build')}</button>`;
 if(tab==='staff'){const p=parity(s);body=`<p>${this.L('equal')}</p><div class="hsecCandidates">${EMPLOYEES.map(d=>`<article><div class="hsecNpcPortrait" data-candidate="${d.id}">${hsecIcon('management')}</div><b>${esc(d.name)}</b><small>HSEC · Nivel 1</small><strong>${this.format(d.hireCost)}</strong><button data-hire="${d.id}" ${h.employee||s.office.level<2?'disabled':''} class="primary">${h.employee?.id===d.id?this.L('npc'):this.L('hire')}</button></article>`).join('')}</div>${h.employee?`<div class="hsecNext"><b>${this.L('npc')} · <span id="hsecNpcState">${this.L(h.employee.state)}</span></b><small>${esc(h.employee.blocked||'Turno 06:00–20:00 · descanso nocturno')}</small><button data-action="inspection">${this.L('inspection')}</button></div>`:''}<h3>${this.L('parity')}</h3><p>${p.women} / ${p.total} mujeres · ${p.men} / ${p.total} hombres</p><small>${this.L('small')}</small>`;}
 if(tab==='orders')body=h.orders.length?h.orders.slice().reverse().map(o=>`<article class="hsecOrder">${hsecIcon('management')}<div><b>${esc(assetDefinition(h.assets.find(a=>a.id===o.assetId)?.type)?.name||o.assetId)}</b><small>${esc(o.problem)} · ${this.L(o.status)}</small><span>${this.format(o.cost)} · ${o.seconds} s · ${this.L(o.component)}</span>${o.status==='pending'?`<div class="hsecActions"><button data-repair="${o.id}">${this.L('repair')}</button><button data-assign="${o.id}" ${h.employee?'':'disabled'}>${this.L('assign')}</button></div>`:''}</div></article>`).join(''):`<p>${this.L('empty')}</p>`;
 if(tab==='history')body=`<p>${this.L('noOffline')}</p>`+h.history.slice(-20).reverse().map(r=>`<article class="hsecHistory"><b>${r.score}/100</b><span>D${1+Math.floor(r.time/B.daySeconds)} · ${Math.floor(r.time%B.daySeconds)} s</span><small>${r.critical} ${this.L('critical').toLowerCase()}${r.reasons.length?' · '+esc(r.reasons.join(' · ')):''}</small></article>`).join('');
 this.showModal(`<div class="hsecPanel">${heading}<div class="hsecBody">${body}</div></div>`);document.querySelector('#modalCard').classList.add('hsecModal');this.bindPanel();// Personnel HSEC is management-only; do not request or render 3D candidate GLBs.
 }
 bindPanel(){const root=document.querySelector('#modalCard');root.querySelectorAll('[data-hsec-tab]').forEach(b=>b.onclick=()=>this.open(b.dataset.hsecTab));root.querySelector('[data-action="build"]')?.addEventListener('click',()=>{this.panelOpen=false;this.hideModal();this.mode=true;this.openBuilder();});root.querySelector('[data-action="office"]')?.addEventListener('click',()=>{this.panelOpen=false;this.hideModal();this.manageOffice();});root.querySelector('[data-action="inspection"]')?.addEventListener('click',()=>this.run(()=>startInspection(this.state()),'Inspección iniciada; el prevencionista recorrerá la red segura.'));root.querySelectorAll('[data-goto]').forEach(b=>b.onclick=()=>{const [x,z]=b.dataset.goto.split(',').map(Number);this.panelOpen=false;this.hideModal();this.onGoto?.({x,z});});
 for(const [attr,fn]of Object.entries({hire:id=>hire(this.state(),id),boost:id=>boostAsset(this.state(),id),inspect:id=>inspectAsset(this.state(),id),upgrade:id=>upgradeAsset(this.state(),id),remove:id=>retireAsset(this.state(),id),repair:id=>assignOrder(this.state(),id,'player'),assign:id=>assignOrder(this.state(),id,'npc')}))root.querySelectorAll('[data-'+attr+']').forEach(b=>b.onclick=()=>this.run(()=>fn(b.dataset[attr])));
 }
 decorateBuilder(builder){this.builder=builder;if(!active(this.state()))return;const b=document.createElement('button');b.className='hsecBuilderEntry';b.innerHTML=hsecIcon('management',true)+'<span>HSEC</span>';b.onclick=()=>{this.mode=true;builder.render();};builder.host.querySelector('.builderCategories')?.append(b);}
 renderBuilder(builder){
  this.builder=builder;const host=builder.host;
  host.classList.toggle('hsecDraftMode',!!this.drawing||!!this.coneZone);
  if(this.coneZone){builder.store.hideDetail();host.classList.remove('catalogTray');this.renderConeZone(host);return;}
  if(this.drawing){builder.store.hideDetail();host.classList.remove('catalogTray');this.renderDraft(host);return;}
  builder.renderStore(this.category,this.selected,id=>{this.category=id;builder.render();},id=>{this.selected=id;builder.render();});
 }
 focus(){if(this.coneZone)return {x:8,z:-9,key:'coneZone-'+this.coneZone.count,height:1,distance:14};if(!this.drawing)return {x:1,z:2};const d=assetDefinition(this.drawing.type),a=this.drawing;const pts=a.points;if(d.route){const f=this.draftFocus||{x:0,z:3};return {x:f.x,z:f.z,key:d.id+'-pan',height:.5,distance:Math.max(14,8+(pts?.length||0)*1.5)};}const center=pts?.length?{x:pts[pts.length-1].x,z:pts[pts.length-1].z}:this.draftFocus;return {...center,key:d.id+'-'+(pts?.length||0),height:d.h,distance:Math.min(14,Math.max(9,6+Math.max(d.w,d.d)*.6))};}
 purchaseFixed(type){const d=assetDefinition(type);if(!d?.fixed)return false;return this.run(()=>buildAsset(this.state(),type,suggestedPose(this.state(),type)),this.L('construction'));}
 beginDraft(type){const s=this.state(),d=assetDefinition(type);
  if(type==='cone'){this.coneZone={count:Math.min(6,Math.max(4,s.hsec.kitCones||6))};this.world.setConeZone(this.coneZone.count);this.builder.render();return;}
  if(type==='shed'&&s.hsec.assets.some(a=>a.type==='shed')){this.open('assets');return;}
  if(d?.route){this.drawing={type,x:0,z:0,rotation:0,points:[]};this.draftFocus=d.route==='linear'?{x:8,z:-5}:{x:0,z:3};this.world.setDraft(null);this.builder.render();return;}
  this.drawing={type,...suggestedPose(s,type)};const pts=this.drawing.points;this.draftFocus=pts?.length?{x:pts.reduce((n,p)=>n+p.x,0)/pts.length,z:pts.reduce((n,p)=>n+p.z,0)/pts.length}:{x:this.drawing.x,z:this.drawing.z};this.world.setDraft(this.drawing);this.builder.render();}
 pick(p){if(!this.drawing)return false;const a=this.drawing,d=assetDefinition(a.type),h=ensureHsec(this.state()),q=snapPoint(p,h,d.route||null);if(d.route){if(!a.points)a.points=[];const max=d.route==='linear'?8:12;if(a.points.length>=max)return true;const last=a.points[a.points.length-1];if(last&&Math.hypot(q.x-last.x,q.z-last.z)<.4)return true;a.points.push({...q});if(a.points.length)a.x=a.points[0].x,a.z=a.points[0].z;this.draftFocus={x:q.x,z:q.z};this.redraw();return true;}if(d.fixed){a.x=d.fixed.x;a.z=d.fixed.z;}else Object.assign(a,q);this.redraw();return true;}
 renderDraft(host){const a=this.drawing,d=assetDefinition(a.type),pts=a.points||[],needsPoints=d.route&&pts.length<2,error=needsPoints?null:validateAsset(this.state(),a.type,a),cost=a.type==='cone'&&this.state().hsec.kitCones?0:needsPoints?0:priceFor(d,pts);
 const routeLen=d.route&&pts.length>=2?pts.slice(1).reduce((n,p,i)=>n+Math.hypot(p.x-pts[i].x,p.z-pts[i].z),0):0;
 const statusText=needsPoints?(pts.length===0?'Toca el terreno para colocar el primer punto':'Toca para añadir el siguiente punto'):d.route?(error||`Ruta de ${routeLen.toFixed(1)} m · ${pts.length} puntos`):(error||`${d.name} · ${this.format(d.price)}`);
 host.innerHTML=`<div class="draftIdentity">${hsecIcon(d.category)}<span><b>${esc(d.name)}</b><small class="${error?'draftError':''}" role="status">${esc(statusText)}</small></span></div><div class="draftTools">${d.route&&pts.length>0?`<button id="hsecUndo">${icon('back')}Deshacer</button>`:''}${!d.route&&!d.fixed?`<button id="hsecRotate">${icon('rotate')}${this.L('rotate')}</button>`:''}</div><strong class="buildCost">${icon('wallet')}${this.format(cost)}</strong><button id="hsecConfirm" class="primary" ${needsPoints||error||this.state().cash<cost?'disabled':''}>${icon('check')}${this.L('build')}</button><button id="hsecCancel" class="iconButton" aria-label="${this.L('cancel')}">${icon('close')}</button><small class="draftGestureHint">${d.route?'Toca el suelo para añadir puntos · arrastra para mirar':'Toca el suelo para ubicar · arrastra para mirar · pinza para zoom'}</small>`;
 host.classList.add('hsecDraftMode');host.querySelector('#hsecCancel').onclick=()=>this.cancelDraft();host.querySelector('#hsecConfirm').onclick=()=>{if(this.run(()=>buildAsset(this.state(),a.type,a),this.L('construction'))){this.cancelDraft();this.onSave();}};host.querySelector('#hsecRotate')?.addEventListener('click',()=>{a.rotation+=Math.PI/4;this.redraw();});host.querySelector('#hsecUndo')?.addEventListener('click',()=>{if(pts.length>0){pts.pop();if(pts.length)a.x=pts[0].x,a.z=pts[0].z;this.redraw();}});
 }
 renderConeZone(host){const s=this.state(),h=ensureHsec(s),count=this.coneZone.count,free=Math.min(count,h.kitCones),paid=count-free,cost=paid*25;
  host.innerHTML=`<div class="draftIdentity">${hsecIcon('boundaries')}<span><b>Kit de Seguridad</b><small>Conos distribuidos en el perímetro de mantenimiento</small></span></div><div class="coneZoneControls"><button id="coneMinus" ${count<=4?'disabled':''}>−</button><span class="coneCount">${count}</span><button id="conePlus" ${count>=8?'disabled':''}>+</button></div><small class="coneZoneInfo">${free>0?free+' del kit gratuito':''}${paid>0?(free>0?' + ':'')+paid+' × $25':''}</small><button id="hsecConfirm" class="primary" ${s.cash<cost?'disabled':''}>${icon('check')}Colocar (${count}) ${this.format(cost)}</button><button id="hsecCancel" class="iconButton">${icon('close')}</button>`;
  host.classList.add('hsecDraftMode');
  host.querySelector('#coneMinus')?.addEventListener('click',()=>{this.coneZone.count=Math.max(4,count-1);this.world.setConeZone(this.coneZone.count);this.builder.render();});
  host.querySelector('#conePlus')?.addEventListener('click',()=>{this.coneZone.count=Math.min(8,count+1);this.world.setConeZone(this.coneZone.count);this.builder.render();});
  host.querySelector('#hsecConfirm').onclick=()=>{if(this.run(()=>buildConeZone(this.state(),count),'Conos colocados')){this.coneZone=null;this.world.setConeZone(0);this.onSave();this.builder.render();}};
  host.querySelector('#hsecCancel').onclick=()=>this.cancelDraft();
 }
 panFocus(dx,dz){if(!this.draftFocus)return;this.draftFocus={x:this.draftFocus.x+dx,z:this.draftFocus.z+dz};}
 redraw(){const a=this.drawing;if(a.points?.length){a.x=a.points[0].x;a.z=a.points[0].z;}this.world.setDraft(a.points?.length===0?null:a);this.builder.render();}
 cancelDraft(){this.drawing=null;this.draftFocus=null;this.coneZone=null;this.world.setDraft(null);this.world.setConeZone?.(0);this.builder?.host.classList.remove('hsecDraftMode');this.builder?.render();}
}
